-- ============================================
-- PERSONAS: cada fila del Excel. Titular y familiares del mismo expediente.
-- ES_TITULAR se copia de PARENTESCOS al guardar (lo mantiene el handler)
-- para poder exigir un solo titular activo por expediente.
-- NRO_DOCUMENTO es texto: guarda ceros a la izquierda y códigos alfanuméricos.
-- La edad no se guarda: se calcula desde FECHA_NACIMIENTO.
-- ============================================
CREATE TABLE IF NOT EXISTS "PERSONAS" (
    "ID_PERSONA" INT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT "PK_PERSONAS" PRIMARY KEY,
    "ID_EXPEDIENTE" INT NOT NULL CONSTRAINT "FK_PERSONAS_EXPEDIENTE" REFERENCES "EXPEDIENTES" ("ID_EXPEDIENTE") ON DELETE CASCADE,
    "ID_PARENTESCO" INT NOT NULL CONSTRAINT "FK_PERSONAS_PARENTESCO" REFERENCES "PARENTESCOS" ("ID_PARENTESCO"),
    "ES_TITULAR" BOOLEAN NOT NULL DEFAULT FALSE,
    "APELLIDO_PATERNO" VARCHAR(80) NULL,
    "APELLIDO_MATERNO" VARCHAR(80) NULL,
    "NOMBRES" VARCHAR(120) NOT NULL,
    "SEXO" CHAR(1) NULL CONSTRAINT "CHK_PERSONAS_SEXO" CHECK ("SEXO" IN ('F', 'M')),
    "ID_NACIONALIDAD" INT NULL CONSTRAINT "FK_PERSONAS_NACIONALIDAD" REFERENCES "NACIONALIDADES" ("ID_NACIONALIDAD"),
    "FECHA_NACIMIENTO" DATE NULL,
    "ID_TIPO_DOCUMENTO" INT NULL CONSTRAINT "FK_PERSONAS_TIPO_DOCUMENTO" REFERENCES "TIPOS_DOCUMENTO" ("ID_TIPO_DOCUMENTO"),
    "NRO_DOCUMENTO" VARCHAR(30) NULL,
    "ACTIVO" BOOLEAN NOT NULL DEFAULT TRUE,
    "FECHA_CREACION" TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS "IX_PERSONAS_EXPEDIENTE" ON "PERSONAS" ("ID_EXPEDIENTE");
CREATE INDEX IF NOT EXISTS "IX_PERSONAS_DOCUMENTO" ON "PERSONAS" ("ID_TIPO_DOCUMENTO", "NRO_DOCUMENTO");
-- Un solo titular activo por expediente
CREATE UNIQUE INDEX IF NOT EXISTS "UX_PERSONAS_TITULAR" ON "PERSONAS" ("ID_EXPEDIENTE")
    WHERE "ES_TITULAR" AND "ACTIVO";
